DECLARE iv jsonb;sm jsonb;tid uuid;aid uuid;token text:='instrument-v3-rollback-only';r jsonb;res jsonb:='[]';
BEGIN
 sm:=population_top3000_202608_202609_v1.ref01_practical_census_manifest_v3();
 SELECT jsonb_build_object('scope_sha256','8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd','policy_sha256',s.policy_sha256,'cohort_sha256',s.snapshot_sha256,'membership_acceptance_sha256',m.acceptance_sha256,'instrument_source_set_sha256',sm->>'source_set_sha256','canonical_mapping_sha256',sm->>'canonical_mapping_sha256') INTO iv FROM population_top3000_202608_202609_v1.ref01_practical_snapshot_v1 s JOIN population_top3000_202608_202609_v1.ref01_practical_membership_v1 m USING(snapshot_sha256);
 tid:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF01','DERIVE','practical-instrument-point-v3:'||(iv->>'cohort_sha256')||':'||(iv->>'instrument_source_set_sha256'),'{"kind":"PRACTICAL_INSTRUMENT_POINT_V3"}',iv);
 FOR iteration IN 1..2 LOOP
 aid:=gen_random_uuid();
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='LEASED',attempt_id=aid,lease_until=clock_timestamp()+interval '5 minutes',owner_fence=3,stop_generation=1 WHERE task_id=tid;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256) SELECT aid,tid,1,encode(sha256(convert_to(token,'UTF8')),'hex'),3,1,function_sha256 FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='REF01' AND stage='DERIVE';
 IF iteration=1 THEN
