 BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=jsonb_set(input_versions,'{instrument_source_set_sha256}','"wrong"') WHERE task_id=tid;PERFORM population_top3000_202608_202609_v1.ref01_practical_instrument_worker_v3(aid,token);RAISE EXCEPTION 'BAD_SOURCE_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'INSTRUMENT_SOURCE_SET_CHANGED' THEN RAISE;END IF;END;
 BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=jsonb_set(input_versions,'{canonical_mapping_sha256}','"wrong"') WHERE task_id=tid;PERFORM population_top3000_202608_202609_v1.ref01_practical_instrument_worker_v3(aid,token);RAISE EXCEPTION 'BAD_MAPPING_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'INSTRUMENT_SOURCE_SET_CHANGED' THEN RAISE;END IF;END;
 BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_raw SET raw_text=raw_text||' ' WHERE job_id='census:2026-08-03:000001';PERFORM population_top3000_202608_202609_v1.ref01_practical_instrument_worker_v3(aid,token);RAISE EXCEPTION 'BAD_BYTES_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'INSTRUMENT_CENSUS_SOURCE_MISMATCH' THEN RAISE;END IF;END;
 BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET stopped=true WHERE singleton;PERFORM population_top3000_202608_202609_v1.ref01_practical_instrument_worker_v3(aid,token);RAISE EXCEPTION 'BAD_STOP_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'MISSION_HELD_OR_ADMISSION_EXPIRED' THEN RAISE;END IF;END;
 BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET owner_fence=4 WHERE singleton;PERFORM population_top3000_202608_202609_v1.ref01_practical_instrument_worker_v3(aid,token);RAISE EXCEPTION 'BAD_OWNER_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'CONTROLLER_OWNERSHIP_CHANGED' THEN RAISE;END IF;END;
 END IF;
 r:=population_top3000_202608_202609_v1.ref01_adjudication_route_v3(aid,token,'DERIVE');
 IF (r#>>'{commit_receipt,new_committed_units}')::int<>(CASE iteration WHEN 1 THEN 3345 ELSE 3000 END) THEN RAISE EXCEPTION 'WRONG_COMMIT_COUNT %',r;END IF;
 IF (population_top3000_202608_202609_v1.ref01_practical_instrument_worker_v3(aid,token)#>>'{commit_receipt,new_committed_units}')::int<>0 THEN RAISE EXCEPTION 'REPLAY_DUPLICATES';END IF;
 PERFORM population_top3000_202608_202609_v1.pipeline_finish_v1(aid,token,r);
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_commit WHERE task_id=tid AND new_committed_units>0) THEN RAISE EXCEPTION 'NO_ACTUAL_COMMIT';END IF;
 res:=res||jsonb_build_array(jsonb_build_object('kind',(SELECT payload->>'kind' FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid),'output_sha256',r#>>'{commit_receipt,output_sha256}','units',r#>>'{commit_receipt,new_committed_units}'));
 tid:=(r#>>'{commit_receipt,explicit_successor_task_id}')::uuid;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 WHERE ticker='NBN' AND company_id IS NULL AND NOT eligible AND content->>'identity_basis'='CONFLICT_WITH_CANONICAL_ISSUER_MAPPING' AND content->>'company_id' IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 WHERE ticker='NBN') THEN RAISE EXCEPTION 'WRONG_ISSUER_NBN_ACCEPTED';END IF;
 INSERT INTO instrument_test_receipt VALUES(jsonb_build_object('result','PASS','useful_commit_chains',res,'source_manifest',sm-'sources','source_bodies',14,'census_rows',13044,'candidate_associations',3345,'supported_dated_instruments',3000,'nbn_wrong_issuer_rejected',true,'policy_source_owner_stop_rejected',true,'idempotent_replays',true,'full_period_instruments_complete',false,'family_accepted',false,'new_http_requests',0,'all_test_mutations_rolled_back',true));
END $test$;
SELECT v FROM instrument_test_receipt;
ROLLBACK;

