CREATE TABLE population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3(
 cohort_sha256 text NOT NULL,source_set_sha256 text NOT NULL,source_job_id text NOT NULL,source_ordinal integer NOT NULL,
 company_id text,ticker text NOT NULL,point_date date NOT NULL,eligible boolean NOT NULL,
