CREATE TABLE population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3(
 cohort_sha256 text NOT NULL,source_set_sha256 text NOT NULL,company_id text NOT NULL,ticker text NOT NULL,point_date date NOT NULL,
