REVOKE ALL ON population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3,population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 FROM PUBLIC,anon,authenticated;
ALTER TABLE population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 ENABLE ROW LEVEL SECURITY;
ALTER TABLE population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION population_top3000_202608_202609_v1.ref01_practical_census_manifest_v3() RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $f$
DECLARE z record;n int:=0;rows_n int:=0;prev_cursor text;items jsonb:='[]';
BEGIN
 FOR z IN SELECT j.job_id,j.snapshot_date,j.page_number,j.params,j.status,r.raw_text,r.sha256,r.source_bytes,r.evidence,r.received_at FROM population_top3000_202608_202609_v1.acquisition_job j JOIN population_top3000_202608_202609_v1.acquisition_raw r USING(job_id) WHERE j.kind='CENSUS' AND j.snapshot_date='2026-08-03' ORDER BY j.page_number LOOP
 n:=n+1;
 IF z.page_number<>n OR z.status<>'COMPLETE' OR z.sha256 IS DISTINCT FROM encode(sha256(convert_to(z.raw_text,'UTF8')),'hex') OR z.source_bytes<>octet_length(z.raw_text) OR z.evidence->>'wire_sha256' IS DISTINCT FROM z.sha256 OR z.evidence->>'http_status' IS DISTINCT FROM '200' OR z.evidence->>'provider' IS DISTINCT FROM 'Massive' OR z.evidence->>'route' IS DISTINCT FROM '/v3/reference/tickers' OR z.evidence->'request_params' IS DISTINCT FROM z.params THEN RAISE EXCEPTION 'INSTRUMENT_CENSUS_SOURCE_MISMATCH';END IF;
 IF n=1 THEN
 IF z.params IS DISTINCT FROM '{"date":"2026-08-03","sort":"ticker","limit":"1000","order":"asc","active":"true","locale":"us","market":"stocks"}'::jsonb THEN RAISE EXCEPTION 'INSTRUMENT_CENSUS_REQUEST_MISMATCH';END IF;
 ELSIF z.params IS DISTINCT FROM jsonb_build_object('cursor',prev_cursor) OR prev_cursor IS NULL THEN RAISE EXCEPTION 'INSTRUMENT_CENSUS_CURSOR_MISMATCH';END IF;
 prev_cursor:=nullif(z.evidence->>'next_cursor','');
 IF z.raw_text::jsonb->>'status' IS DISTINCT FROM 'OK' OR (z.raw_text::jsonb->>'count')::int IS DISTINCT FROM jsonb_array_length(z.raw_text::jsonb->'results') OR z.raw_text::jsonb->>'request_id' IS DISTINCT FROM z.evidence->>'request_id' OR (CASE WHEN prev_cursor IS NULL THEN NULL ELSE 'https://api.massive.com/v3/reference/tickers?cursor='||prev_cursor END) IS DISTINCT FROM z.raw_text::jsonb->>'next_url' THEN RAISE EXCEPTION 'INSTRUMENT_CENSUS_BODY_CHAIN_MISMATCH';END IF;
 IF jsonb_typeof(z.raw_text::jsonb->'results') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INSTRUMENT_CENSUS_BODY_MISMATCH';END IF;
 rows_n:=rows_n+jsonb_array_length(z.raw_text::jsonb->'results');
 items:=items||jsonb_build_array(jsonb_build_object('job_id',z.job_id,'page_number',z.page_number,'sha256',z.sha256,'source_bytes',z.source_bytes,'evidence_sha256',encode(sha256(convert_to(z.evidence::text,'UTF8')),'hex'),'received_at',z.received_at));
 END LOOP;
 IF n<>14 OR rows_n<>13044 OR prev_cursor IS NOT NULL THEN RAISE EXCEPTION 'INSTRUMENT_CENSUS_CHAIN_INCOMPLETE';END IF;
 RETURN jsonb_build_object('canonical_mapping_sha256',(SELECT encode(sha256(convert_to(string_agg(ticker||':'||case_key,E'\n' ORDER BY ticker COLLATE "C",case_key COLLATE "C"),'UTF8')),'hex') FROM population_top3000_202608_202609_v1.ref01_security_decision_v2 WHERE run_key='ref01-company-reconciliation-v2-20261023'),'sources',items,'source_set_sha256',encode(sha256(convert_to(items::text,'UTF8')),'hex'),'source_rows',rows_n,'point_date','2026-08-03','historical_receipt_proven',false);
END $f$;
CREATE FUNCTION population_top3000_202608_202609_v1.ref01_practical_instrument_worker_v3(p_attempt uuid,p_token text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $f$
DECLARE tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;s jsonb;m jsonb;acc text;h text;sh text;k text;z record;v jsonb;n bigint:=0;out_hash text;nextid uuid;is_ok boolean;identity_ok boolean;identity_state text;anchors jsonb;canonical jsonb;
BEGIN
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 PERFORM population_top3000_202608_202609_v1.ref01_practical_guard_v1();
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid;
 k:=t.payload->>'kind';h:=t.input_versions->>'cohort_sha256';
 IF t.family_id IS DISTINCT FROM 'REF01' OR k IS NULL OR k NOT IN('PRACTICAL_INSTRUMENT_POINT_V3','PRACTICAL_DATED_INSTRUMENT_V3') THEN RAISE EXCEPTION 'INSTRUMENT_KIND_REQUIRED';END IF;
 SELECT content INTO STRICT m FROM population_top3000_202608_202609_v1.ref01_practical_snapshot_v1 WHERE snapshot_sha256=h;
 SELECT acceptance_sha256 INTO STRICT acc FROM population_top3000_202608_202609_v1.ref01_practical_membership_v1 WHERE snapshot_sha256=h AND acceptance_sha256=encode(sha256(convert_to(content::text,'UTF8')),'hex');
 IF h IS DISTINCT FROM '2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' OR encode(sha256(convert_to(m::text,'UTF8')),'hex') IS DISTINCT FROM h OR t.input_versions->>'policy_sha256' IS DISTINCT FROM m->>'policy_sha256' OR t.input_versions->>'membership_acceptance_sha256' IS DISTINCT FROM acc THEN RAISE EXCEPTION 'INSTRUMENT_FROZEN_INPUT_MISMATCH';END IF;
 SELECT jsonb_object_agg((i->>'company_id')||':'||(i->>'ticker'),i->>'census_record_sha256') INTO anchors FROM jsonb_array_elements(m->'instruments') i;
 SELECT jsonb_object_agg(ticker,case_key) INTO canonical FROM population_top3000_202608_202609_v1.ref01_security_decision_v2 WHERE run_key='ref01-company-reconciliation-v2-20261023';
 s:=population_top3000_202608_202609_v1.ref01_practical_census_manifest_v3();sh:=s->>'source_set_sha256';
 IF sh IS DISTINCT FROM t.input_versions->>'instrument_source_set_sha256' OR s->>'canonical_mapping_sha256' IS DISTINCT FROM t.input_versions->>'canonical_mapping_sha256' THEN RAISE EXCEPTION 'INSTRUMENT_SOURCE_SET_CHANGED';END IF;
 IF t.stage='VALIDATE' THEN RETURN jsonb_build_object('state','BLOCKED','blocker_code','PRACTICAL_INSTRUMENT_FULL_WINDOW_EVIDENCE_REQUIRED_V3','resumption_condition',jsonb_build_object('point_date','2026-08-03','remaining_calendar_dates',60,'independent_source_review_required',true,'historical_receipt_proven',false,'full_period_instruments_complete',false,'engineering_assignment_event_id',t.input_versions->'engineering_successor_event_id','cohort_sha256',h,'policy_sha256',m->>'policy_sha256','instrument_source_set_sha256',sh,'automatic_retry',false));END IF;
 IF t.stage<>'DERIVE' THEN RAISE EXCEPTION 'INSTRUMENT_STAGE_REQUIRED';END IF;
 IF k='PRACTICAL_INSTRUMENT_POINT_V3' THEN
 FOR z IN WITH chosen AS(SELECT value->>'company_id' company_id FROM jsonb_array_elements(m->'companies')) SELECT r.job_id,r.sha256,r.received_at,x.value rec,x.ordinality::int ord,c.company_id FROM population_top3000_202608_202609_v1.acquisition_raw r CROSS JOIN LATERAL jsonb_array_elements(r.raw_text::jsonb->'results') WITH ORDINALITY x JOIN chosen c ON c.company_id='CIK:'||(x.value->>'cik') WHERE r.job_id IN(SELECT value->>'job_id' FROM jsonb_array_elements(s->'sources')) ORDER BY r.job_id COLLATE "C",x.ordinality LOOP
 identity_ok:=coalesce(anchors->>(z.company_id||':'||(z.rec->>'ticker'))=encode(sha256(convert_to(z.rec::text,'UTF8')),'hex'),false);
 identity_state:=CASE WHEN identity_ok THEN 'REVIEWED_FROZEN_IDENTITY_POINT' WHEN canonical ? (z.rec->>'ticker') AND canonical->>(z.rec->>'ticker') IS DISTINCT FROM z.company_id THEN 'CONFLICT_WITH_CANONICAL_ISSUER_MAPPING' ELSE 'UNREVIEWED_VENDOR_CIK_ASSOCIATION' END;
 is_ok:=identity_ok AND coalesce(z.rec->>'active'='true' AND z.rec->>'type' IN('CS','ADRC') AND z.rec->>'primary_exchange' IN('XNYS','XNAS','XASE','ARCX','BATS','IEXG') AND z.rec->>'market'='stocks' AND z.rec->>'locale'='us',false);
 v:=jsonb_build_object('policy_sha256',m->>'policy_sha256','cohort_sha256',h,'membership_acceptance_sha256',acc,'source_set_sha256',sh,'source_job_id',z.job_id,'source_sha256',z.sha256,'source_ordinal',z.ord,'source_record_sha256',encode(sha256(convert_to(z.rec::text,'UTF8')),'hex'),'source_record',z.rec,'vendor_company_candidate',z.company_id,'company_id',CASE WHEN identity_ok THEN z.company_id ELSE NULL END,'canonical_mapping_sha256',s->>'canonical_mapping_sha256','ticker',z.rec->>'ticker','point_date','2026-08-03','received_at',z.received_at,'eligibility_state',case when is_ok then 'SOURCE_SUPPORTED_COMMON_POINT' else 'NON_ELIGIBLE_OR_UNRESOLVED_TYPE_EXCHANGE_POINT' end,'eligible',is_ok,'identity_basis',identity_state,'vendor_cik_is_not_sufficient_identity',true,'interval_start',NULL,'interval_end',NULL,'original_historical_receipt_proven',false,'full_period_instruments_complete',false,'family_accepted',false);
 INSERT INTO population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 VALUES(h,sh,z.job_id,z.ord,CASE WHEN identity_ok THEN z.company_id ELSE NULL END,z.rec->>'ticker','2026-08-03',is_ok,v,encode(sha256(convert_to(v::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;
 IF FOUND THEN n:=n+1;END IF;
 IF (SELECT content FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 WHERE cohort_sha256=h AND source_set_sha256=sh AND source_job_id=z.job_id AND source_ordinal=z.ord) IS DISTINCT FROM v THEN RAISE EXCEPTION 'INSTRUMENT_POINT_REPLAY_CONFLICT';END IF;
 END LOOP;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 WHERE cohort_sha256=h AND source_set_sha256=sh)<>3345 THEN RAISE EXCEPTION 'INSTRUMENT_POINT_COUNT_CHANGED';END IF;
 SELECT encode(sha256(convert_to(string_agg(record_sha256,E'\n' ORDER BY source_job_id COLLATE "C",source_ordinal),'UTF8')),'hex') INTO out_hash FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 WHERE cohort_sha256=h AND source_set_sha256=sh;
 nextid:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF01','DERIVE','practical-dated-instrument-v3:'||h||':'||sh,jsonb_build_object('kind','PRACTICAL_DATED_INSTRUMENT_V3'),t.input_versions||jsonb_build_object('point_output_sha256',out_hash),tid);
 ELSE
 SELECT encode(sha256(convert_to(string_agg(record_sha256,E'\n' ORDER BY source_job_id COLLATE "C",source_ordinal),'UTF8')),'hex') INTO out_hash FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 WHERE cohort_sha256=h AND source_set_sha256=sh;
 IF out_hash IS DISTINCT FROM t.input_versions->>'point_output_sha256' OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 WHERE cohort_sha256=h AND source_set_sha256=sh AND record_sha256 IS DISTINCT FROM encode(sha256(convert_to(content::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'INSTRUMENT_POINT_INPUT_CHANGED';END IF;
 FOR z IN SELECT * FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 WHERE cohort_sha256=h AND source_set_sha256=sh AND eligible ORDER BY company_id COLLATE "C",ticker COLLATE "C" LOOP
 v:=z.content-'source_record'||jsonb_build_object('point_record_sha256',z.record_sha256,'security_identity',jsonb_build_object('composite_figi',z.content#>>'{source_record,composite_figi}','share_class_figi',z.content#>>'{source_record,share_class_figi}','primary_exchange',z.content#>>'{source_record,primary_exchange}','type',z.content#>>'{source_record,type}'),'evidence_semantics','ONE_VENDOR_DATED_LISTING_POINT_NOT_FULL_INTERVAL','is_frozen_anchor_instrument',anchors ? (z.company_id||':'||z.ticker));
 INSERT INTO population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 VALUES(h,sh,z.company_id,z.ticker,z.point_date,v,encode(sha256(convert_to(v::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;
 IF FOUND THEN n:=n+1;END IF;
 IF (SELECT content FROM population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 WHERE cohort_sha256=h AND source_set_sha256=sh AND company_id=z.company_id AND ticker=z.ticker AND point_date=z.point_date) IS DISTINCT FROM v THEN RAISE EXCEPTION 'INSTRUMENT_DATED_REPLAY_CONFLICT';END IF;
 END LOOP;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 WHERE cohort_sha256=h AND source_set_sha256=sh)<>3000 OR (SELECT count(DISTINCT company_id) FROM population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 WHERE cohort_sha256=h AND source_set_sha256=sh)<>3000 THEN RAISE EXCEPTION 'INSTRUMENT_DATED_COUNT_CHANGED';END IF;
